    const words=topicWords("water").map(([fi,en,bn])=>'<article class="finland-water-word"><strong lang="fi">'+esc(fi)+'</strong><span>'+esc(en)+'</span><small lang="bn">'+esc(bn)+'</small>'+finlandWordActionsMarkup(fi,en,bn,topics[5].title)+'</article>').join("");
    const places=[["HELSINKI ARCHIPELAGO","Suomenlinna","saari · lautta","A city-to-island scene: ask about the ferry and find Finnish place words.","https://www.visitfinland.com/en/articles/10-islands-to-visit-in-finnish-archipelago/","Kysyn lautan aikataulua.","I ask about the ferry timetable.","ফেরির সময়সূচি জিজ্ঞেস করি।","🏰"],["TURKU ARCHIPELAGO","Nauvo · Nagu","saaristo · satama","A coastal stop for island routes, harbours and everyday travel vocabulary.","https://www.visitfinland.com/en/articles/10-islands-to-visit-in-finnish-archipelago/","Nauvo on saaristossa.","Nauvo is in the archipelago.","নাউভো দ্বীপপুঞ্জে অবস্থিত।","⛵"],["LAKELAND","Saimaa","järvi · laiva","Move inland from the coast and notice Finnish words for lake journeys and water landscapes.","https://www.visitfinland.com/en/practical-tips/getting-around/","Saimaa on suuri järvialue.","Saimaa is a large lake region.","সাইমা একটি বড় হ্রদ-অঞ্চল।","🛶"]].map(([tag,title,words,description,url,phrase,en,bn,icon])=>'<article class="finland-water-place"><span>'+icon+' '+esc(tag)+'</span><h4>'+esc(title)+'</h4><b lang="fi">'+esc(words)+'</b><p>'+esc(description)+'</p><strong lang="fi">'+esc(phrase)+'</strong><small>'+esc(en)+'</small><small lang="bn">'+esc(bn)+'</small><button type="button" data-topic-speak="'+esc(phrase)+'">▶ Hear this Finnish phrase</button><a href="'+url+'" target="_blank" rel="noreferrer">Explore the destination ↗</a></article>').join("");
    const steps=[["01","Choose a destination and route","Valitsen paikan ja reitin.","বেড়ানোর জায়গা ও পথ বেছে নিই।"],["02","Check the ferry or ship timetable","Tarkistan lautta-aikataulun.","ফেরির সময়সূচি যাচাই করি।"],["03","Read traffic notices and safety signs","Luen tiedotteet ja ohjeet.","যাতায়াতের নোটিশ ও নিরাপত্তা-নির্দেশনা পড়ি।"],["04","Check the local water information","Katson vesitiedot.","স্থানীয় পানির তথ্য দেখি।"]].map(([number,en,fi,bn])=>'<article class="finland-water-step"><span>'+number+'</span><div><strong>'+esc(en)+'</strong><b lang="fi">'+esc(fi)+'</b><small lang="bn">'+esc(bn)+'</small></div><button type="button" data-topic-speak="'+esc(fi)+'" aria-label="Hear '+esc(fi)+' in Finnish">▶</button></article>').join("");
    const services=[["FERRY ROUTES","Finferries routes and timetables","Search route notices, schedules, bookings and ferry locations.","https://www.finferries.fi/en/ferry-traffic/ferries-and-schedules.html","Find a route ↗","⛴"],["LIVE MARITIME INFORMATION","Fintraffic Traffic Situation","Open the map for current traffic information, marine incidents and navigation warnings.","https://liikennetilanne.fintraffic.fi/?lang=en","Check marine traffic ↗","⚓"],["WATER OBSERVATIONS","Vesi.fi blue-green algae map","Read local observations. Water conditions can change quickly, so check current notices.","https://www.vesi.fi/en/blue-green-algae-situation/","Check water observations ↗","🌿"],["SEA RESEARCH","Finnish Environment Institute","Explore monitoring and current information about the Baltic Sea and Finland’s waters.","https://www.ymparisto.fi/en/state-environment/water/state-baltic-sea","Learn about the Baltic Sea ↗","🌊"]].map(([tag,title,description,url,label,icon])=>'<a class="finland-water-service" href="'+url+'" target="_blank" rel="noreferrer"><span>'+icon+' '+esc(tag)+'</span><strong>'+esc(title)+'</strong><p>'+esc(description)+'</p><b>'+esc(label)+'</b></a>').join("");
    return '<section class="finland-water-journey" aria-labelledby="finland-water-heading"><div class="finland-water-hero"><div class="finland-water-hero-copy"><span class="page-kicker">LAKES, SEA & ARCHIPELAGO · PRE-A1–A2</span><h2 id="finland-water-heading">A little Finnish, from lake shore to island ferry</h2><p>Meet the landscapes, learn the words for water travel, and practise how to check the route and local conditions.</p><span lang="fi">meri · järvi · saaristo</span></div><div class="finland-water-hero-art" role="img" aria-label="Original illustration of a small ferry crossing between pine-covered Finnish islands"><svg viewBox="0 0 440 190" aria-hidden="true"><defs><linearGradient id="water-sky" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#b9dce9"/><stop offset="1" stop-color="#e9e5c9"/></linearGradient></defs><path fill="url(#water-sky)" d="M0 0h440v190H0z"/><circle cx="365" cy="37" r="21" fill="#f2d397"/><path fill="#799684" d="M0 108 27 53l29 55 26-48 31 54 27-62 35 64 31-49 31 50 29-67 34 65 31-48 36 62v57H0z"/><path fill="#315846" d="M0 131 28 74l30 57 25-48 31 52 29-67 34 68 30-50 33 52 30-63 34 62 29-45 36 64v54H0z"/><path fill="#76aaa9" d="M0 145q67-11 134 0t134 0 172-2v47H0z"/><path fill="#a4c8c1" d="M0 158q78-9 155 1t151 0 134-2v33H0z"/><path fill="#d5c19c" d="M0 178q100-15 220 0t220-4v16H0z"/><path fill="#e9eee8" d="M160 131h112q15 0 21 17H148q3-17 12-17z"/><path fill="#b65c48" d="M193 113h46l18 18h-74z"/><path fill="#f7f4e8" d="M202 117h20v12h-20zm25 0h10v12h-10z"/><path fill="#415a59" d="M148 148h147v10H148z"/><path fill="#334c4a" d="M170 159h11v5h-11zm92 0h11v5h-11z"/><path fill="#f7f4e8" d="M25 160q40-7 80 0t80 0" opacity=".8"/></svg><span>lautta · ferry across the saaristo</span></div></div><section class="finland-water-scenes" aria-labelledby="finland-water-scenes-title"><div class="finland-water-heading-row"><div><span class="page-kicker">CHOOSE A WATER SCENE</span><h3 id="finland-water-scenes-title">What would you like to explore?</h3></div><span>Finnish phrases, audio and bilingual help</span></div><div class="finland-water-scene-tabs" role="group" aria-label="Choose a Finnish water and travel scene">'+sceneButtons+'</div><div id="finland-water-scene-detail">'+waterSceneMarkup()+'</div></section><section class="finland-water-words" aria-labelledby="finland-water-words-title"><div class="finland-water-heading-row"><div><span class="page-kicker">WATER WORDS · VESISANAT</span><h3 id="finland-water-words-title">Twelve useful words</h3></div><span>Tap any word to hear it</span></div><div class="finland-water-word-grid">'+words+'</div><p class="finland-water-word-note"><strong lang="fi">sinilevä</strong> is commonly called blue-green algae in English; scientifically, it refers to cyanobacteria. <span lang="bn">sinilevä-কে সাধারণভাবে নীল-সবুজ শৈবাল বলা হয়; বৈজ্ঞানিকভাবে এটি সায়ানোব্যাকটেরিয়া।</span></p></section><section class="finland-water-places" aria-labelledby="finland-water-places-title"><div class="finland-water-heading-row"><div><span class="page-kicker">FOLLOW THE WATER</span><h3 id="finland-water-places-title">Three places, three water stories</h3></div><span>Explore a place and say a phrase</span></div><div class="finland-water-place-grid">'+places+'</div></section><section class="finland-water-steps" aria-labelledby="finland-water-steps-title"><div class="finland-water-heading-row"><div><span class="page-kicker">PLAN · CHECK · EXPLORE</span><h3 id="finland-water-steps-title">A simple water-trip checklist</h3></div><span>One Finnish phrase for each step</span></div><div class="finland-water-step-grid">'+steps+'</div><p class="finland-water-safety"><strong>Before you swim:</strong> local water observations are periodic and conditions can change quickly with weather. Check the current Vesi.fi map and local notices; avoid swimming where blue-green algae are present.<small lang="bn">সাঁতারের আগে: স্থানীয় পানির পর্যবেক্ষণ নির্দিষ্ট বিরতিতে হয়, আর আবহাওয়ায় অবস্থা দ্রুত বদলাতে পারে। বর্তমান Vesi.fi মানচিত্র ও স্থানীয় নোটিশ দেখুন; পানিতে নীল-সবুজ শৈবাল থাকলে সাঁতার এড়িয়ে চলুন।</small><a href="https://www.vesi.fi/en/blue-green-algae-situation/" target="_blank" rel="noreferrer">Vesi.fi · current observations and safety guidance ↗</a></p></section><section class="finland-water-services" aria-labelledby="finland-water-services-title"><div class="finland-water-heading-row"><div><span class="page-kicker">CURRENT ROUTES & WATER INFORMATION</span><h3 id="finland-water-services-title">Explore the official sources</h3></div><span>Routes, conditions and notices can change</span></div><div class="finland-water-service-grid">'+services+'</div></section><section class="finland-water-media"><span class="page-kicker">SEE AND HEAR MORE FINNISH</span><h3>Watch a little real Finnish</h3><p>Yle’s learning hub offers Finnish video and listening material; captions and topics depend on the programme.</p><a href="https://yle.fi/a/20-10002426" target="_blank" rel="noreferrer">Open Yle’s Finnish learning materials ↗</a></section><p class="finland-water-sources">Sources checked 22 October 2026: <a href="https://www.finferries.fi/en/ferry-traffic/ferries-and-schedules.html" target="_blank" rel="noreferrer">Finferries · routes and timetables</a> · <a href="https://liikennetilanne.fintraffic.fi/?lang=en" target="_blank" rel="noreferrer">Fintraffic · marine traffic and notices</a> · <a href="https://www.vesi.fi/en/blue-green-algae-situation/" target="_blank" rel="noreferrer">Vesi.fi · blue-green algae observations</a> · <a href="https://www.ymparisto.fi/en/state-environment/water/state-baltic-sea" target="_blank" rel="noreferrer">Finnish Environment Institute · Baltic Sea</a> · <a href="https://www.visitfinland.com/en/articles/10-islands-to-visit-in-finnish-archipelago/" target="_blank" rel="noreferrer">Visit Finland · Finnish islands</a>.</p></section>';
