    return '<div class="finland-market-season-detail"><div><h4>'+esc(season.title)+'</h4><p>'+esc(season.note)+'</p><small lang="bn">'+esc(season.bn)+'</small></div><div class="finland-market-season-words">'+cards+'</div></div>';
