    const sceneButtons=scenes.map(([id,title,words])=>'<button type="button" data-culture-scene="'+esc(id)+'" aria-pressed="'+(activeCultureScene===id)+'"><strong>'+esc(title)+'</strong><small lang="fi">'+esc(words)+'</small></button>').join("");
    const words=topicWords("culture").map(([fi,en,bn])=>'<article class="finland-culture-word"><strong lang="fi">'+esc(fi)+'</strong><span>'+esc(en)+'</span><small lang="bn">'+esc(bn)+'</small><button type="button" data-topic-speak="'+esc(fi.split(" / ")[0])+'" aria-label="Hear '+esc(fi)+' in Finnish">▶ Listen</button></article>').join("");
    const steps=[["01","Check the local instructions","Tarkistan ohjeet.","আমি নির্দেশনা দেখে নিই।"],["02","Shower before you enter","Käyn suihkussa.","আমি গোসল করে নিই।"],["03","Ask if you are unsure","Kysyn ensin.","নিশ্চিত না হলে আগে জিজ্ঞেস করি।"],["04","Take a break when you need one","Pidän tauon tarvittaessa.","প্রয়োজন হলে বিরতি নিই।"]].map(([number,en,fi,bn])=>'<article class="finland-culture-step"><span>'+number+'</span><div><strong>'+esc(en)+'</strong><b lang="fi">'+esc(fi)+'</b><small lang="bn">'+esc(bn)+'</small></div><button type="button" data-topic-speak="'+esc(fi)+'" aria-label="Hear '+esc(fi)+' in Finnish">▶</button></article>').join("");
    const dialogue=[["HOST","Tervetuloa saunaan.","Welcome to the sauna.","সাউনায় স্বাগতম।"],["GUEST","Onko tässä saunassa omat ohjeet?","Does this sauna have its own instructions?","এই সাউনায় কি আলাদা নির্দেশনা আছে?"],["HOST","Kyllä. Lue ohjeet oven vieressä.","Yes. Read the instructions beside the door.","হ্যাঁ। দরজার পাশের নির্দেশনাটি পড়ুন।"],["GUEST","Pitääkö minun käyttää uimapukua?","Do I need to wear a swimsuit?","আমার কি সাঁতারের পোশাক পরতে হবে?"]].map(([speaker,fi,en,bn])=>'<article class="finland-culture-dialogue-line"><div><span>'+esc(speaker)+'</span><strong lang="fi">'+esc(fi)+'</strong><p>'+esc(en)+'</p><small lang="bn">'+esc(bn)+'</small></div><button type="button" data-topic-speak="'+esc(fi)+'" aria-label="Hear Finnish: '+esc(fi)+'">▶</button></article>').join("");
    const media=[["PRE-A1 · A1","Finnish basics in short videos","Yle Areena’s beginner collection has 20 episodes for first steps and useful phrases.","Suomen kielen alkeet","https://areena.yle.fi/1-3882033"],["A2 · B2","Everyday Finnish in action","Short service encounters with exercises for independent practice.","Asiointisuomea","https://yle.fi/a/20-146213"],["ALL LEVELS","Find your next Finnish video","Browse Yle’s Finnish learning materials, including beginner videos and simplified news.","Yle Oppiminen · Finnish","https://yle.fi/a/20-10002426"]].map(([level,title,description,label,url])=>'<a class="finland-culture-media-card" href="'+url+'" target="_blank" rel="noreferrer"><span>'+esc(level)+'</span><strong>'+esc(title)+'</strong><p>'+esc(description)+'</p><b>▶ '+esc(label)+' ↗</b></a>').join("");
    return '<section class="finland-culture-journey" aria-labelledby="finland-culture-heading"><div class="finland-culture-hero"><div class="finland-culture-hero-copy"><span class="page-kicker">CULTURE, SAUNA & MEDIA · PRE-A1–A2</span><h2 id="finland-culture-heading">A little Finnish, a little löyly</h2><p>Learn the words, ask thoughtful questions, and explore Finnish culture at your own pace.</p><span lang="fi">sauna · löyly · rauhassa</span></div><div class="finland-culture-hero-art" role="img" aria-label="Original illustration of a lakeside sauna among Finnish pines at twilight"><svg viewBox="0 0 440 190" aria-hidden="true"><defs><linearGradient id="culture-dusk" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#425e70"/><stop offset="1" stop-color="#d5bca1"/></linearGradient></defs><path fill="url(#culture-dusk)" d="M0 0h440v190H0z"/><circle cx="342" cy="40" r="22" fill="#f2d69a"/><path fill="#26483d" d="M0 115 38 48l37 67 27-48 40 64 33-70 40 72 35-55 37 58 40-79 39 78 29-50 42 65v75H0z"/><path fill="#17372f" d="M0 146q50-19 100 0t100 0 100 0 100 0 100 0v44H0z"/><path fill="#87a8a0" d="M0 157q52-12 105 0t105 0 105 0 125 0v33H0z"/><path fill="#d9c3a4" d="M137 92h142v66H137z"/><path fill="#8b5f49" d="m126 94 82-53 82 53z"/><path fill="#796153" d="M158 104h38v54h-38z"/><path fill="#f4e5bf" d="M214 108h42v27h-42z"/><path fill="#41584f" d="M224 114h22v16h-22z"/><path fill="#bd8b5d" d="M147 151h121v8H147z"/><path fill="#e9d4ae" d="M277 104q-10-18 3-25 11-8 4-18m5 43q7-15 1-23" fill-opacity=".62"/></svg><span>iltasauna · an evening sauna</span></div></div><aside class="finland-culture-heritage"><span aria-hidden="true">✳</span><p><strong>A living tradition, many ways to enjoy it.</strong> UNESCO added sauna culture in Finland to its Representative List in 2020. Practices differ across people and places; this lesson helps you ask, listen and follow the local guidance.<small lang="bn">২০২০ সালে UNESCO ফিনল্যান্ডের সাউনা সংস্কৃতিকে মানবতার অমূর্ত সাংস্কৃতিক ঐতিহ্যের তালিকায় যুক্ত করে। মানুষ ও স্থানভেদে রীতি আলাদা—জিজ্ঞেস করুন, শুনুন এবং স্থানীয় নির্দেশনা মানুন।</small><a href="https://ich.unesco.org/en/RL/sauna-culture-in-finland-01596" target="_blank" rel="noreferrer">UNESCO · Sauna culture in Finland ↗</a></p></aside><section class="finland-culture-scenes" aria-labelledby="finland-culture-scenes-title"><div class="finland-culture-heading-row"><div><span class="page-kicker">CHOOSE A MOMENT</span><h3 id="finland-culture-scenes-title">What would you like to say?</h3></div><span>Hear the phrase in Finnish</span></div><div class="finland-culture-scene-tabs" role="group" aria-label="Choose a sauna conversation situation">'+sceneButtons+'</div><div id="finland-culture-scene-detail">'+cultureSceneMarkup()+'</div></section><section class="finland-culture-words" aria-labelledby="finland-culture-words-title"><div class="finland-culture-heading-row"><div><span class="page-kicker">A SMALL WORD COLLECTION</span><h3 id="finland-culture-words-title">Nine words for a sauna visit</h3></div><span>Tap to listen</span></div><div class="finland-culture-word-grid">'+words+'</div><p class="finland-culture-word-note"><strong lang="fi">vihta</strong> is also called <strong lang="fi">vasta</strong> in some regions. The same sauna culture has many local and personal traditions.</p></section><section class="finland-culture-routine" aria-labelledby="finland-culture-routine-title"><div class="finland-culture-heading-row"><div><span class="page-kicker">GO AT YOUR OWN PACE</span><h3 id="finland-culture-routine-title">Four phrases for feeling comfortable</h3></div><span>Choose what works for you</span></div><div class="finland-culture-step-grid">'+steps+'</div><p class="finland-culture-practical"><strong>Before a visit:</strong> shower first, check whether swimwear is required, and follow the venue’s instructions. Some Finnish public saunas require swimwear; there is no single dress rule for every place. Step out whenever you need a break.<small lang="bn">যাওয়ার আগে গোসল করুন, সাঁতারের পোশাক লাগবে কি না দেখে নিন, এবং স্থানের নির্দেশনা মানুন। কিছু ফিনিশ পাবলিক সাউনায় সাঁতারের পোশাক বাধ্যতামূলক; সব জায়গার নিয়ম এক নয়। প্রয়োজন হলে বিরতি নিন।</small><a href="https://finland.fi/life-society/5-tips-for-enjoying-the-sauna-like-people-in-finland/" target="_blank" rel="noreferrer">ThisisFINLAND · five sauna tips ↗</a></p></section><section class="finland-culture-dialogue" aria-labelledby="finland-culture-dialogue-title"><div class="finland-culture-heading-row"><div><span class="page-kicker">LISTEN · READ · REPEAT</span><h3 id="finland-culture-dialogue-title">Check the house rules</h3></div><span>Short, useful Finnish</span></div><div class="finland-culture-dialogue-card">'+dialogue+'</div></section><section class="finland-culture-media" aria-labelledby="finland-culture-media-title"><div class="finland-culture-heading-row"><div><span class="page-kicker">SEE AND HEAR FINNISH</span><h3 id="finland-culture-media-title">Watch a little real Finnish</h3></div><span>Official Yle learning pages</span></div><div class="finland-culture-media-grid">'+media+'</div><p class="finland-culture-source-note">Yle’s media opens on Yle’s own site. Availability, captions and language support can vary by programme.</p></section><p class="finland-culture-sources">Sources checked 22 October 2026: <a href="https://ich.unesco.org/en/RL/sauna-culture-in-finland-01596" target="_blank" rel="noreferrer">UNESCO · living heritage</a> · <a href="https://finland.fi/life-society/5-tips-for-enjoying-the-sauna-like-people-in-finland/" target="_blank" rel="noreferrer">ThisisFINLAND · sauna tips</a> · <a href="https://areena.yle.fi/1-3882033" target="_blank" rel="noreferrer">Yle Areena · Finnish basics</a> · <a href="https://yle.fi/a/20-146213" target="_blank" rel="noreferrer">Yle · Asiointisuomea</a> · <a href="https://yle.fi/a/20-10002426" target="_blank" rel="noreferrer">Yle · Finnish study materials</a>.</p></section>';
