  function housingSceneMarkup(sceneId=activeHousingScene){
    const scenes={
      search:{title:"Ask if the home is still available",tag:"FIND A HOME · ASUNNONHAKU",icon:"🔎",copy:"Rental listings often use the search word vuokra-asunto. Check the address, monthly cost, size and what the listing says is included.",bn:"ভাড়ার বাসার বিজ্ঞাপনে vuokra-asunto শব্দটি খুঁজুন। ঠিকানা, মাসিক খরচ, আকার এবং বিজ্ঞাপনে কোন খরচ অন্তর্ভুক্ত বলা হয়েছে তা দেখুন।",phrase:"Onko asunto vielä vapaa?",en:"Is the apartment still available?",bnPhrase:"অ্যাপার্টমেন্টটি কি এখনো খালি আছে?",reply:"Kyllä, asunto on vielä vapaa.",replyEn:"Yes, the apartment is still available.",replyBn:"হ্যাঁ, অ্যাপার্টমেন্টটি এখনো খালি আছে।"},
      viewing:{title:"Arrange an apartment viewing",tag:"A VIEWING · ASUNTONÄYTTÖ",icon:"🏠",copy:"At a viewing, look at the home and ask how to apply. Check the real address and note any existing defects before you move in.",bn:"বাসা দেখতে গিয়ে ঘরটি দেখুন এবং কীভাবে আবেদন করতে হবে জিজ্ঞেস করুন। ঠিকানা মিলিয়ে নিন এবং ওঠার আগে আগে থেকেই থাকা ত্রুটি লিখে রাখুন।",phrase:"Voisinko tulla katsomaan asuntoa?",en:"Could I come to see the apartment?",bnPhrase:"আমি কি অ্যাপার্টমেন্টটি দেখতে আসতে পারি?",reply:"Tervetuloa katsomaan asuntoa.",replyEn:"You are welcome to come and see the apartment.",replyBn:"আপনি অ্যাপার্টমেন্টটি দেখতে আসতে পারেন।"},
      agreement:{title:"Read the agreement and costs",tag:"THE AGREEMENT · VUOKRASOPIMUS",icon:"📄",copy:"Ask which charges are included in the rent. Water, electricity, insurance and other costs depend on the written agreement and the home.",bn:"ভাড়ার মধ্যে কোন খরচ অন্তর্ভুক্ত তা জিজ্ঞেস করুন। পানি, বিদ্যুৎ, বীমা ও অন্যান্য খরচ চুক্তি ও বাসাভেদে আলাদা হতে পারে।",phrase:"Sisältyykö vesi vuokraan?",en:"Is water included in the rent?",bnPhrase:"ভাড়ার মধ্যে কি পানির খরচ আছে?",reply:"Tarkistan sen vuokrasopimuksesta.",replyEn:"I’ll check it in the tenancy agreement.",replyBn:"আমি ভাড়ার চুক্তিতে তা দেখে নেব।"}
    };
    const scene=scenes[sceneId]||scenes.search;
    return `<div class="finland-housing-scene-detail"><div class="finland-housing-scene-art" aria-hidden="true"><span>${scene.icon}</span><small>${esc(scene.tag)}</small></div><div class="finland-housing-scene-copy"><span class="page-kicker">EVERYDAY FINNISH · ASK, LISTEN, REPEAT</span><h4>${esc(scene.title)}</h4><p>${esc(scene.copy)}</p><p lang="bn">${esc(scene.bn)}</p><div class="finland-housing-dialogue"><article><div><span>YOU</span><strong lang="fi">${esc(scene.phrase)}</strong><p>${esc(scene.en)}</p><small lang="bn">${esc(scene.bnPhrase)}</small></div><button type="button" data-topic-speak="${esc(scene.phrase)}" aria-label="Hear Finnish: ${esc(scene.phrase)}">▶</button></article><article><div><span>HELPER</span><strong lang="fi">${esc(scene.reply)}</strong><p>${esc(scene.replyEn)}</p><small lang="bn">${esc(scene.replyBn)}</small></div><button type="button" data-topic-speak="${esc(scene.reply)}" aria-label="Hear Finnish: ${esc(scene.reply)}">▶</button></article></div></div></div>`;
  }
