    const words=topicWords("housing").map(([fi,en,bn])=>`<article class="finland-housing-word"><strong lang="fi">${esc(fi)}</strong><span>${esc(en)}</span><small lang="bn">${esc(bn)}</small><button type="button" data-topic-speak="${esc(fi)}" aria-label="Hear ${esc(fi)} in Finnish">▶ Listen</button></article>`).join("");
