    const sources=[["INFOFINLAND · RENTAL HOME","Finding a home","Search terms, viewings, applications and what to check in a rental home.","https://infofinland.fi/en/housing/rental-home"],["INFOFINLAND · TENANCY AGREEMENT","Read the lease","Written agreements, rent, deposits, utilities and ending a tenancy.","https://infofinland.fi/housing/rental-home/tenancy-agreement"],["KKV · CONSUMER GUIDANCE","Security deposits","Current guidance on deposits, payments and rental-apartment matters.","https://www.kkv.fi/en/consumer-affairs/housing/rental-apartments/security-deposit-for-a-rented-apartment/"]].map(([kicker,title,description,url])=>`<a class="finland-housing-source-card" href="${url}" target="_blank" rel="noreferrer"><span>${esc(kicker)}</span><strong>${esc(title)}</strong><p>${esc(description)}</p><b>Open official guidance ↗</b></a>`).join("");
